package ai.nethra.planner.llm;
import ai.nethra.planner.graph.TravelGraphState; import com.fasterxml.jackson.databind.*; import com.fasterxml.jackson.databind.node.*; import java.net.URI; import java.net.http.*;
public class OpenAiLlmClient implements LlmClient {
  private final String apiKey; private final String model; private final ObjectMapper mapper; private final HttpClient http=HttpClient.newHttpClient();
  public OpenAiLlmClient(String apiKey,String model,ObjectMapper mapper){this.apiKey=apiKey;this.model=model;this.mapper=mapper;}
  public String summarize(TravelGraphState state){ try { ObjectNode body=mapper.createObjectNode(); body.put("model",model); ArrayNode messages=body.putArray("messages"); ObjectNode sys=messages.addObject(); sys.put("role","system"); sys.put("content","You write concise, warm travel plan summaries. Never invent prices or facts beyond the supplied draft."); ObjectNode user=messages.addObject(); user.put("role","user"); user.put("content","Rewrite this travel plan summary in at most 90 words, keeping every number unchanged: " + SummaryTemplates.summarize(state)); HttpRequest req=HttpRequest.newBuilder(URI.create("https://api.openai.com/v1/chat/completions")).header("Authorization","Bearer "+apiKey).header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofString(mapper.writeValueAsString(body))).build(); HttpResponse<String> res=http.send(req,HttpResponse.BodyHandlers.ofString()); if(res.statusCode()/100!=2) return SummaryTemplates.summarize(state); JsonNode root=mapper.readTree(res.body()); String text=root.path("choices").path(0).path("message").path("content").asText(""); return text.isBlank()?SummaryTemplates.summarize(state):text.trim(); } catch(Exception e){ return SummaryTemplates.summarize(state); } }
}
